// task 5b step 2 --pre: synthetic maximal-overlap staging.
// Camera just behind the nearest of the two farthest-apart zombies in the
// current room, looking through it at the far one (task 5's overlap scene,
// recreated as a --pre so the noise floor is taken IN the staged scene).
// Zombies are already frozen (the harness freezes before --pre), so the
// poses read here pin the scene for every capture below.
(async () => {
  const zs = __sdfGame.zombies();
  const rid = Number(__sdfGame.room().replace('room', ''));
  // Room interiors (game-level.ts: BAND_HALF 0.8 + ROOM_HALF 4).
  const bounds = { 3: [0.8, 8.8, 0.8, 8.8], 4: [-8.8, -0.8, 0.8, 8.8] }[rid];
  const inRoom = zs.filter(z => z.room === rid);
  let best = null, bd = -1;
  for (const a of inRoom) for (const b of inRoom) {
    if (a.id === b.id) continue;
    const d = Math.hypot(a.pos[0] - b.pos[0], a.pos[2] - b.pos[2]);
    if (d > bd) { bd = d; best = [a, b]; }
  }
  if (!best) return { error: 'no pair in room ' + rid, zombies: zs };
  const [A, Bf] = best;
  const dx = Bf.pos[0] - A.pos[0], dz = Bf.pos[2] - A.pos[2];
  const L = Math.hypot(dx, dz), ux = dx / L, uz = dz / L;
  // Back off behind A toward -dir, shrinking until the camera sits 0.6 m
  // inside the room (setPose teleports without collision resolve).
  let back = 1.6;
  const inside = (x, z) => x > bounds[0] + 0.6 && x < bounds[1] - 0.6 && z > bounds[2] + 0.6 && z < bounds[3] - 0.6;
  for (let k = 0; k < 10 && !inside(A.pos[0] - ux * back, A.pos[2] - uz * back); k++) back *= 0.7;
  const cx = A.pos[0] - ux * back, cz = A.pos[2] - uz * back;
  // Look vector (sin yaw, -cos yaw) = (ux, uz)  =>  yaw = atan2(ux, -uz).
  __sdfGame.setPose(cx, cz, Math.atan2(ux, -uz));
  return {
    room: rid, near: A.id, far: Bf.id, gap_m: +L.toFixed(2), backoff_m: +back.toFixed(2),
    cam: [+cx.toFixed(2), +cz.toFixed(2)], others: inRoom.filter(z => z.id !== A.id && z.id !== Bf.id).map(z => z.id),
    poses: inRoom.map(z => ({ id: z.id, pos: z.pos.map(v => +v.toFixed(2)) })),
  };
})()
